DELETE FROM rag_clause t WHERE NOT EXISTS (SELECT 1 FROM rag_clause_seed s WHERE s.clause_id = t.clause_id);
INSERT INTO rag_clause (clause_id, law_name, article, title, body, embedding, embedding_model, embedding_revision, chunk_index, source_version, loaded_at)
SELECT clause_id, law_name, article, title, body, embedding, embedding_model, embedding_revision, chunk_index, source_version, now() FROM rag_clause_seed
ON CONFLICT (clause_id) DO UPDATE SET law_name = EXCLUDED.law_name, article = EXCLUDED.article, title = EXCLUDED.title, body = EXCLUDED.body, embedding = EXCLUDED.embedding, embedding_model = EXCLUDED.embedding_model, embedding_revision = EXCLUDED.embedding_revision, chunk_index = EXCLUDED.chunk_index, source_version = EXCLUDED.source_version, loaded_at = EXCLUDED.loaded_at
WHERE (rag_clause.law_name, rag_clause.article, rag_clause.title, rag_clause.body, rag_clause.embedding, rag_clause.embedding_model, rag_clause.embedding_revision, rag_clause.chunk_index, rag_clause.source_version) IS DISTINCT FROM (EXCLUDED.law_name, EXCLUDED.article, EXCLUDED.title, EXCLUDED.body, EXCLUDED.embedding, EXCLUDED.embedding_model, EXCLUDED.embedding_revision, EXCLUDED.chunk_index, EXCLUDED.source_version);

DELETE FROM rag_query_template t WHERE NOT EXISTS (SELECT 1 FROM rag_query_template_seed s WHERE s.template_key = t.template_key);
INSERT INTO rag_query_template (template_key, text, embedding, embedding_model, embedding_revision)
SELECT template_key, text, embedding, embedding_model, embedding_revision FROM rag_query_template_seed
ON CONFLICT (template_key) DO UPDATE SET text = EXCLUDED.text, embedding = EXCLUDED.embedding, embedding_model = EXCLUDED.embedding_model, embedding_revision = EXCLUDED.embedding_revision
WHERE (rag_query_template.text, rag_query_template.embedding, rag_query_template.embedding_model, rag_query_template.embedding_revision) IS DISTINCT FROM (EXCLUDED.text, EXCLUDED.embedding, EXCLUDED.embedding_model, EXCLUDED.embedding_revision);

-- 문서와 질문이 모두 한 모델·revision 인지 확인한다(섞이면 검색 점수를 비교할 수 없다)
DO $$
BEGIN
    IF (SELECT count(DISTINCT (embedding_model, embedding_revision)) FROM (
            SELECT embedding_model, embedding_revision FROM rag_clause
            UNION ALL SELECT embedding_model, embedding_revision FROM rag_query_template) r) > 1 THEN
        RAISE EXCEPTION 'rag_clause·rag_query_template 의 임베딩 모델·revision 이 섞였다';
    END IF;
END $$;
